'use strict';

// MODULES //

var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Evaluates the polynomial P(x) in exp(x) ≈ 1 + x + x²P(x) for |x| ≤ ln(2)/2.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @private
* @param {number} x - value at which to evaluate the polynomial
* @returns {number} evaluated polynomial
*/
function polyvalP( x ) {
	var p;

	p = float64ToFloat32( 1.9875691500e-4 );
	p = float64ToFloat32( (p * x) + 1.3981999507e-3 );
	p = float64ToFloat32( (p * x) + 8.3334519073e-3 );
	p = float64ToFloat32( (p * x) + 4.1665795894e-2 );
	p = float64ToFloat32( (p * x) + 1.6666665459e-1 );
	p = float64ToFloat32( (p * x) + 5.0000001201e-1 );

	return p;
}


// EXPORTS //

module.exports = polyvalP;
